-- Run manually on the target database. Updates only the bilingual privacy page and form notice.
-- Other CMS fields are preserved. This intentionally replaces the existing privacy text.
BEGIN;
SET LOCAL standard_conforming_strings = on;
WITH patched AS (SELECT id, jsonb_set(jsonb_set(jsonb_set(jsonb_set(content, '{el,pages,privacy-policy}', '{"title":"Πολιτική απορρήτου","intro":"Πώς το Get2Gether Project διαχειρίζεται τα στοιχεία σου όταν επισκέπτεσαι την ιστοσελίδα, επικοινωνείς μαζί μας ή υποβάλλεις αξιολόγηση. Ενημέρωση: 24 Σεπτεμβρίου 2026.","body":"## Επικοινωνία\n\nΤο Get2Gether Project διαχειρίζεται τα στοιχεία που υποβάλλονται μέσω αυτής της ιστοσελίδας. Για ερωτήσεις σχετικά με τα προσωπικά σου δεδομένα ή για την άσκηση των δικαιωμάτων σου, επικοινώνησε στο get2getherproject@gmail.com ή στο +30 698 215 1046. Η ενημέρωση αυτή αφορά την ιστοσελίδα και τις φόρμες της. Το εφαρμοστέο πλαίσιο περιλαμβάνει τον Γενικό Κανονισμό Προστασίας Δεδομένων της ΕΕ (ΓΚΠΔ), τον ελληνικό νόμο 4624/2019 και, όπου εφαρμόζεται, τον νόμο 3471/2006 για τις ηλεκτρονικές επικοινωνίες.\n\n## Ποια στοιχεία συλλέγουμε\n\nΤα αιτήματα για εργαστήρια και ιδιωτικές εκδηλώσεις περιλαμβάνουν το όνομα, το email, το μήνυμα και το θέμα που επιλέγεις. Ανάλογα με τη φόρμα και όσα επιλέγεις να συμπληρώσεις, μπορεί επίσης να περιλαμβάνουν τηλέφωνο, προτιμώμενη ημερομηνία, αριθμό ατόμων, τοποθεσία, προτίμηση εσωτερικού ή εξωτερικού χώρου, προϋπολογισμό, προτιμήσεις φαγητού ή ποτού και ενδιαφέρον για δημιουργική δραστηριότητα. Οι αξιολογήσεις περιλαμβάνουν όνομα, email, βαθμολογία και κείμενο. Αποθηκεύουμε επίσης τη γλώσσα και τον χρόνο υποβολής, ένα αναγνωριστικό αιτήματος και την κατάσταση διαχείρισης ή ελέγχου. Μην καταχωρίζεις ευαίσθητες πληροφορίες ή προσωπικά στοιχεία άλλων ανθρώπων στα πεδία ελεύθερου κειμένου.\n\n## Γιατί χρησιμοποιούμε τα στοιχεία σου\n\nΧρησιμοποιούμε τα αιτήματα εκδηλώσεων για να απαντήσουμε και να εξετάσουμε τις υπηρεσίες που ζητάς, συμπεριλαμβανομένων ενεργειών πριν από τη σύναψη σύμβασης κατόπιν αιτήματός σου (άρθρο 6 παρ. 1 στοιχ. β ΓΚΠΔ). Η λοιπή επικοινωνία, ο έλεγχος και η δημοσίευση αξιολογήσεων και τα μέτρα κατά επαναλαμβανόμενων ή καταχρηστικών υποβολών εξυπηρετούν τα έννομα συμφέροντά μας για επικοινωνία με επισκέπτες, κοινοποίηση σχετικών εμπειριών πελατών και ασφάλεια της υπηρεσίας (άρθρο 6 παρ. 1 στοιχ. στ). Μπορείς να εναντιωθείς στην επεξεργασία που βασίζεται σε έννομα συμφέροντα. Στοιχεία που απαιτούνται για συγκεκριμένη νομική υποχρέωση υποβάλλονται σε επεξεργασία με αυτή τη βάση (άρθρο 6 παρ. 1 στοιχ. γ). Η αποστολή αιτήματος δεν αποτελεί επιβεβαιωμένη κράτηση.\n\n## Αξιολογήσεις και δημόσια στοιχεία\n\nΟι αξιολογήσεις ελέγχονται πριν δημοσιευτούν. Εφόσον εγκριθούν, το όνομα που καταχωρίζεις, η βαθμολογία, το κείμενο και η σχετική ημερομηνία μπορεί να εμφανίζονται δημόσια στη σελίδα αξιολογήσεων. Το email σου δεν δημοσιεύεται. Η υποβολή αξιολόγησης είναι προαιρετική. Επικοινώνησε μαζί μας αν θέλεις να ζητήσεις διόρθωση ή αφαίρεση δημοσιευμένης αξιολόγησης. Τα αιτήματα εργαστηρίων και ιδιωτικών εκδηλώσεων δεν εμφανίζονται δημόσια.\n\n## Αποθήκευση, πρόσβαση και πάροχοι υπηρεσιών\n\nΟι υποβολές αποθηκεύονται στην κεντρική βάση δεδομένων της ιστοσελίδας και είναι διαθέσιμες σε εξουσιοδοτημένους διαχειριστές για την εξυπηρέτηση αιτημάτων και τον έλεγχο αξιολογήσεων. Τεχνικοί πάροχοι φιλοξενίας, αποθήκευσης βάσης δεδομένων και συντήρησης μπορεί να επεξεργάζονται πληροφορίες στον βαθμό που απαιτείται για τις υπηρεσίες τους. Η ιστοσελίδα φιλοξενείται στη Vercel. Αν επικοινωνήσεις μέσω email, το μήνυμά σου διαχειρίζεται και ο πάροχος ηλεκτρονικού ταχυδρομείου μας. Δεν έχει συνδεθεί προς το παρόν υπηρεσία αυτόματων ειδοποιήσεων email με τις φόρμες.\n\nΟι πάροχοι μπορεί να επεξεργάζονται τεχνικά στοιχεία ή στοιχεία λογαριασμού εκτός Ελλάδας ή Ευρωπαϊκού Οικονομικού Χώρου. Κάθε τέτοια διαβίβαση πρέπει να στηρίζεται σε νόμιμο μηχανισμό του κεφαλαίου V ΓΚΠΔ, όπως εφαρμοστέα απόφαση επάρκειας ή κατάλληλες συμβατικές εγγυήσεις. Μπορείς να ζητήσεις πληροφορίες για τους παρόχους, τις τοποθεσίες επεξεργασίας και τις εγγυήσεις που αφορούν τα δεδομένα σου.\n\n## Χρόνος διατήρησης\n\nΗ διατήρηση εξαρτάται από τον σκοπό: αν ένα αίτημα παραμένει σε εξέλιξη, αν η οργάνωση εκδήλωσης χρειάζεται συνέχεια, αν μια αξιολόγηση παραμένει σχετική και δημοσιευμένη και αν συγκεκριμένη νομική υποχρέωση ή εκκρεμής διαφορά απαιτεί διατήρηση. Η σήμανση αιτήματος ως ολοκληρωμένου δεν το διαγράφει αυτόματα. Μη δημοσιευμένες αξιολογήσεις και ολοκληρωμένα αιτήματα δεν πρέπει να διατηρούνται όταν έχει λήξει η ανάγκη διαχείρισης, αναγκαίας συνέχειας και τυχόν νόμιμης διατήρησης. Μπορείς να ζητήσεις επανεξέταση της ανάγκης διατήρησης ή διαγραφή.\n\n## Cookies και εξωτερικοί σύνδεσμοι\n\nΔεν χρησιμοποιούμε προς το παρόν εργαλεία ανάλυσης επισκεψιμότητας ή διαφημιστικής παρακολούθησης. Η σύνδεση διαχειριστή χρησιμοποιεί αναγκαίο cookie ταυτοποίησης, όχι διαφημιστικό cookie. Οι υπηρεσίες φιλοξενίας μπορεί να επεξεργάζονται τεχνικές πληροφορίες αιτημάτων, όπως διευθύνσεις IP, για τη λειτουργία, την ασφάλεια και την αντιμετώπιση προβλημάτων. Οι σύνδεσμοι προς Instagram, Facebook, TikTok, Google Drive ή άλλα εξωτερικά άλμπουμ οδηγούν σε υπηρεσίες με δικές τους πρακτικές απορρήτου. Το άνοιγμα συνδέσμου μπορεί να γνωστοποιεί τεχνικές πληροφορίες στην υπηρεσία αυτή και ισχύουν οι δικοί της κανόνες πρόσβασης ή σύνδεσης.\n\n## Επιλογές και δικαιώματα\n\nΜπορείς να περιηγείσαι χωρίς να υποβάλεις φόρμα. Τα υποχρεωτικά πεδία χρειάζονται για τη διαχείριση του αιτήματος ή της αξιολόγησης· χωρίς αυτά η φόρμα δεν υποβάλλεται. Τα προαιρετικά πεδία μπορούν να μείνουν κενά. Η υποβολή δεν σε εγγράφει σε ενημερωτικό δελτίο. Δεν χρησιμοποιούμε τις φόρμες για αποφάσεις αποκλειστικά με αυτοματοποιημένη επεξεργασία που έχουν έννομα ή παρόμοια σημαντικά αποτελέσματα.\n\nΥπό τις προϋποθέσεις του ΓΚΠΔ, μπορείς να ζητήσεις πρόσβαση, διόρθωση, διαγραφή, περιορισμό, φορητότητα και να εναντιωθείς στην επεξεργασία. Όπου η επεξεργασία βασίζεται σε συγκατάθεση, μπορείς να την ανακαλέσεις χωρίς να επηρεάζεται η προηγούμενη νόμιμη επεξεργασία. Στείλε το αίτημά σου στο get2getherproject@gmail.com. Ενδέχεται να χρειαστούν ανάλογες πληροφορίες για την επιβεβαίωση της ταυτότητάς σου. Η συνήθης προθεσμία απάντησης είναι ένας μήνας· αν απαιτείται νόμιμη παράταση, πρέπει να ενημερωθείς εντός αυτής της προθεσμίας.\n\n## Καταγγελίες και αλλαγές\n\nΜπορείς να υποβάλεις καταγγελία στην Αρχή Προστασίας Δεδομένων Προσωπικού Χαρακτήρα μέσω https://www.dpa.gr/polites/katagelia_stin_arxi ή στην αρμόδια αρχή του τόπου κατοικίας ή εργασίας σου. Δεν απαιτείται να επικοινωνήσεις πρώτα μαζί μας για να ασκήσεις αυτό το δικαίωμα. Ενημερώνουμε την πολιτική όταν αλλάζει η επεξεργασία στην ιστοσελίδα· η ημερομηνία στην αρχή προσδιορίζει αυτή την έκδοση."}'::jsonb), '{el,text,privacy}', '"Χρησιμοποιούμε τα στοιχεία σου για τη διαχείριση του αιτήματος ή της αξιολόγησής σου. Στις εγκεκριμένες αξιολογήσεις δημοσιεύονται το όνομα που καταχωρίζεις, η βαθμολογία και το κείμενο· το email δεν δημοσιεύεται. Δες την πολιτική απορρήτου για τους σκοπούς, τη διατήρηση και τα δικαιώματά σου."'::jsonb), '{en,pages,privacy-policy}', '{"title":"Privacy policy","intro":"How Get2Gether Project handles your information when you visit this website, contact us or leave a review. Updated 24 September 2026.","body":"## Who to contact\n\nGet2Gether Project manages the information submitted through this website. For questions about your personal data or to exercise your rights, contact get2getherproject@gmail.com or +30 698 215 1046. This notice concerns this website and its forms. The applicable framework includes the EU General Data Protection Regulation (GDPR), Greek Law 4624/2019 and, where applicable, Greek Law 3471/2006 on electronic communications.\n\n## What we collect\n\nWorkshop and private-event requests contain your name, email address, message and selected topic. Depending on the form and what you choose to provide, they may also contain a phone number, preferred date, guest count, location, indoor/outdoor preference, budget, food or drink preferences and interest in a creative activity. Reviews contain your name, email address, rating and review text. We also store the submission language, submission time, a request identifier and the processing or moderation status. Please do not include sensitive information or other people''s personal details in free-text fields.\n\n## Why we use your information\n\nWe use event inquiries to respond to you and consider the arrangements you request, including steps before entering a contract at your request (Article 6(1)(b) GDPR). Other correspondence, review moderation and publication, and measures against repeated or abusive submissions serve our legitimate interests in communicating with visitors, sharing relevant customer experiences and keeping the service secure (Article 6(1)(f)). You may object to processing based on legitimate interests. Data needed to comply with a specific legal obligation is processed on that basis (Article 6(1)(c)). Sending an inquiry is not a confirmed booking.\n\n## Reviews and public information\n\nReviews are checked before publication. If approved, the name you provide, rating, review text and publication-related date may be visible to everyone on the reviews page. Your email address is not published. Posting a review is optional. Contact us if you want to request correction or removal of a published review. Workshop and private-event requests are not displayed publicly.\n\n## Storage, access and service providers\n\nForm submissions are stored in the website''s central database and are available to authorised administrators for handling requests and moderating reviews. Technical service providers supporting hosting, database storage and website maintenance may process information as needed to provide those services. The website is hosted on Vercel. If you contact us by email, your message is also handled by our email provider. No automatic email notification service is currently connected to the website forms.\n\nService providers may process technical or account data outside Greece or the European Economic Area. Any such transfer must have a lawful basis under Chapter V GDPR, such as an applicable adequacy decision or appropriate contractual safeguards. Contact us to request information about the providers, processing locations and safeguards applicable to your data.\n\n## How long information is kept\n\nRetention depends on the purpose: whether an inquiry is still being answered, whether an event arrangement requires follow-up, whether a review remains relevant and published, and whether a specific legal obligation or an unresolved dispute requires retention. Marking an inquiry as handled does not automatically erase it. Unpublished reviews and completed inquiries should not be kept once their handling, necessary follow-up and any applicable legal retention needs have ended. You can ask us to review whether continued retention is necessary or request erasure.\n\n## Cookies and external links\n\nWe do not currently use analytics or marketing trackers. The administrator sign-in uses a necessary authentication cookie; it is not an advertising cookie. Hosting services may process technical request information such as IP addresses for delivery, security and troubleshooting. Links to Instagram, Facebook, TikTok, Google Drive or other external photo albums lead to services with their own privacy practices. Opening an external link may disclose technical information to that service, and its access or sign-in rules apply.\n\n## Your choices and rights\n\nYou can browse without submitting a form. Required form fields are needed to handle the request or review; without them the form cannot be submitted. Optional fields can be left blank. Submitting a form does not subscribe you to a newsletter. We do not use these forms for solely automated decisions producing legal or similarly significant effects.\n\nSubject to the conditions in the GDPR, you can request access, correction, erasure, restriction, portability and object to processing. Where processing relies on consent, you may withdraw it without affecting earlier lawful processing. Send your request to get2getherproject@gmail.com. We may need proportionate information to verify your identity. The normal response period is one month; where a lawful extension is necessary, you must be informed within that period.\n\n## Complaints and changes\n\nYou can lodge a complaint with the Hellenic Data Protection Authority at https://www.dpa.gr/en/individuals/complaint-to-the-hellenic-dpa or with the competent authority where you live or work. You do not have to contact us first to exercise this right. We update this notice when the website''s processing changes; the date above identifies this version."}'::jsonb), '{en,text,privacy}', '"We use your details to handle your inquiry or review. Approved reviews display your submitted name, rating and text publicly; your email is not published. See the privacy policy for purposes, retention and your rights."'::jsonb) AS updated FROM site_content WHERE id='website')
UPDATE site_content s SET content=p.updated, revision=s.revision+1, updated_at=now() FROM patched p WHERE s.id=p.id AND s.content IS DISTINCT FROM p.updated;
COMMIT;
